import KeyboardCore
//
//  KeyboardViewController+CandidateBar.swift
//  Keyboard
//
//  候选栏与控制器状态之间的薄适配。
//
//  候选栏架构：
//    ┌──────────────────────────────────────────┐
//    │ [cand1] [cand2] ... [scroll right]  [▼] │ ← 左右无极滑动 + 展开按钮
//    └──────────────────────────────────────────┘
//
//  翻页：输入更新后准备多页数据，UICollectionView 仅渲染屏幕附近候选。
//
//  展开后面板（流式布局，填满整个键盘区域）：
//    ┌─────────────────────────────────[▲]─────┐
//    │  [你好] [你好吗] [你] [你们] [你好啊]    │ ← 宽度自适应 + 自动换行
//    │  [你好世界] [你好呀] [你的] ...          │
//    │  ...                          (scroll ↓) │
//    └──────────────────────────────────────────┘
//
import UIKit

// MARK: === 候选栏 ===

extension KeyboardViewController {

    // MARK: --- 候选栏容器 ---

    /// Connects the presentation-only candidate container to controller state.
    func makeCandidateBar() -> UIView {
        let view = CandidateBarView(
            height: candidateBarHeight,
            bottomHitExtension: candidateToKeySpacing,
            backgroundColor: .clear,
            interactionTarget: self,
            expandAction: #selector(handleCandidateBarTrailingButton)
        )
        #if DEBUG && KEYBOARD_WAKE_OWNER_PROBE
            installWakeOwnerProbeControls(on: view)
        #endif
        let collectionView = view.collectionView
        collectionView.dataSource = self
        collectionView.delegate = self
        candidateCollectionView = collectionView
        candidateScrollView = collectionView
        candidateExpandButton = view.expandButton
        candidateExpandButtonWidthConstraint = view.expandButtonWidthConstraint
        fillCandidateBar()
        view.onItemTap = { [weak self] indexPath in
            self?.commitCompactCandidate(at: indexPath)
        }
        return view
    }

    /// Idle trailing control dismisses the keyboard; expandable content still expands.
    @objc func handleCandidateBarTrailingButton() {
        let canExpand = presentedCandidates.contains { $0.kind.expandsCandidateBarPanel }
        if canExpand {
            toggleCandidateExpand()
        } else {
            dismissKeyboard()
        }
    }

    /// 切换候选面板展开/收起。展开面板覆盖在现有键盘之上，
    /// 不拆除底层按键和候选栏，因此切换动画期间没有整页重排。
    @objc func toggleCandidateExpand() {
        if isPinyinPathExpanded {
            dismissPinyinPathExpandedPanel(animated: false)
        }
        isCandidateExpanded.toggle()
        candidatePrefetchRequestSerial += 1
        deferredCandidatePrefetchMode = nil
        updateExpandButtonAppearance()
        if isCandidateExpanded {
            candidatePrefetchMode = .expanded
            if controller.state.pendingPunctuation != nil || controller.state.pendingKaomoji != nil {
                resetCandidateSnapshotFromController()
                fillCandidateBar()
            }
            presentExpandedCandidatePanel()
            if hasMoreCandidates {
                scheduleCandidatePrefetch(mode: .expanded)
            }
        } else {
            candidatePrefetchMode = .bar
            if controller.state.pendingPunctuation != nil || controller.state.pendingKaomoji != nil {
                resetCandidateSnapshotFromController()
                fillCandidateBar()
            }
            dismissExpandedCandidatePanel(animated: true)
        }
    }

    // MARK: --- 刷新 ---

    /// 刷新候选栏内容。
    ///
    /// 每次新的拼音输入时：
    ///   1. 从 RIME 获取第一页候选
    ///   2. 集合视图立即显示第一页，仅渲染可见 cell
    ///   3. 用户实际滚动到末尾时，再按需请求后续页
    func refreshCandidateBar() {
        guard candidateCollectionView != nil else { return }
        let refreshStart = CACurrentMediaTime()

        resetCandidateSnapshotFromController()
        #if DEBUG
            let preeditLength = controller.state.lastRimeOutput?.composition?.preeditText.count ?? 0

            Logger.shared.info(
                "refreshCandidateBar: page1=\(accumulatedCandidates.count), next=\(nextCandidateGlobalIndex), "
                    + "hasMore=\(hasMoreCandidates), preeditLength=\(preeditLength)",
                category: .display
            )
        #endif

        fillCandidateBar()
        let refreshMs = (CACurrentMediaTime() - refreshStart) * 1000
        #if DEBUG
            Logger.shared.performance(
                "CANDIDATES refresh total=\(String(format: "%.1f", refreshMs))ms items=\(accumulatedCandidates.count)"
            )
        #endif
        if refreshMs >= 30 {
            Logger.shared.warning(
                "SLOW CANDIDATES refresh duration=\(String(format: "%.1f", refreshMs))ms "
                    + "items=\(accumulatedCandidates.count) depth=\(candidatePageDepth)",
                category: .performance
            )
        }

        // 滚动回最左侧
        if candidateScrollView.contentOffset.x != 0 {
            candidateScrollView.setContentOffset(.zero, animated: false)
        }

        if isCandidateExpanded {
            refreshExpandedPanel()
        }
        if hasMoreCandidates {
            scheduleCandidatePrefetch(mode: candidatePrefetchMode)
        }
    }

    /// 刷新横向候选列表的数据呈现。`UICollectionView` 自行复用可见 cell，
    /// 不需要为每个已加载候选创建常驻 UIButton。
    func fillCandidateBar(keepScrollPosition: Bool = false) {
        guard let collectionView = candidateCollectionView else {
            Logger.shared.warning("fillCandidateBar: candidateCollectionView is nil", category: .general)
            return
        }
        #if DEBUG
            let renderStart = CACurrentMediaTime()
        #endif
        let items = presentedCandidates

        // Dual-mode trailing control (`PD-CANDIDATE-BAR-IDLE-DISMISS-001`):
        // expandable content keeps expand + swipe-down; idle shows dismiss.
        let canExpand = items.contains { $0.kind.expandsCandidateBarPanel }
        candidateExpandButton?.isHidden = false
        if candidateExpandButtonWidthConstraint?.constant != 56 {
            candidateExpandButtonWidthConstraint?.constant = 56
        }
        if let bar = candidateBar as? CandidateBarView {
            bar.allowsSwipeToExpand = canExpand
        }
        updateExpandButtonAppearance(canExpand: canExpand)
        #if DEBUG && KEYBOARD_WAKE_OWNER_PROBE
            refreshWakeOwnerProbeControls()
        #endif

        let currentOffset = candidateScrollView.contentOffset.x
        collectionView.reloadData()
        if keepScrollPosition {
            collectionView.layoutIfNeeded()
            let maxOffset = max(0, candidateScrollView.contentSize.width - candidateScrollView.bounds.width)
            candidateScrollView.contentOffset.x = min(currentOffset, maxOffset)
        } else if items.isEmpty {
            candidateScrollView.setContentOffset(.zero, animated: false)
        }
        collectionView.alwaysBounceHorizontal = hasMoreCandidates && !items.isEmpty

        #if DEBUG
            Logger.shared.debug(
                "fillCandidateBar collection: items=\(items.count), "
                    + "durationMs=\(String(format: "%.1f", (CACurrentMediaTime() - renderStart) * 1000))",
                category: .display
            )
        #endif
    }

    func appendToCandidateBar(insertedCount: Int? = nil) {
        guard let collectionView = candidateCollectionView,
            let insertedCount,
            insertedCount > 0
        else {
            fillCandidateBar(keepScrollPosition: true)
            return
        }

        let currentCount = collectionView.numberOfItems(inSection: 0)
        let expectedOldCount = max(0, presentedCandidates.count - insertedCount)
        guard currentCount == expectedOldCount else {
            fillCandidateBar(keepScrollPosition: true)
            return
        }

        let indexPaths = (expectedOldCount..<(expectedOldCount + insertedCount)).map {
            IndexPath(item: $0, section: 0)
        }
        let currentOffset = candidateScrollView.contentOffset
        let generation = candidateSnapshotGeneration
        UIView.performWithoutAnimation {
            collectionView.performBatchUpdates {
                collectionView.insertItems(at: indexPaths)
            } completion: { _ in
                guard self.candidateSnapshotGeneration == generation,
                    collectionView === self.candidateCollectionView
                else { return }
                let maxOffset = max(
                    0, self.candidateScrollView.contentSize.width - self.candidateScrollView.bounds.width)
                self.candidateScrollView.contentOffset.x = min(currentOffset.x, maxOffset)
                collectionView.alwaysBounceHorizontal = self.hasMoreCandidates && !self.presentedCandidates.isEmpty
            }
        }
    }

    // MARK: --- 候选数据 ---

    /// 获取当前应显示的候选词列表。
    ///
    /// 无极滑动模式下优先返回累积列表（包含已加载的所有页的候选），
    /// 确保候选栏和展开面板始终显示相同的候选集合。
    func candidateItems() -> [CandidateItem] {
        if !accumulatedCandidates.isEmpty {
            return accumulatedCandidates
        }
        return CandidateBarDataSource.candidateItems(from: controller)
    }

    private func nextGlobalIndexAfterCurrentItems() -> Int {
        let referencedNextIndex = accumulatedCandidates.compactMap { item in
            item.selectionReference?.globalIndex.map { $0 + 1 }
        }.max()
        if let referencedNextIndex { return referencedNextIndex }
        return controller.state.lastRimeOutput?.candidates.count ?? 0
    }

    /// Rebuilds the presentation cache from the controller state.
    ///
    /// Page changes rebuild the keyboard before `refreshCandidateBar()` can run.
    /// When a key both commits composition and returns to letters, this prevents
    /// the newly created candidate bar from reusing stale accumulated candidates.
    func resetCandidateSnapshotFromController() {
        // Placeholder 是旧按钮式候选栏的安全哨兵，不属于当前 collection 快照。
        // 在唯一重建边界过滤一次，避免每个数据源回调都复制并过滤数组。
        let pendingItems: [CandidateItem]?
        if controller.state.pendingPunctuation != nil {
            pendingItems = controller.pendingPunctuationCandidateItems(expanded: isCandidateExpanded)
        } else if controller.state.pendingKaomoji != nil {
            pendingItems = controller.pendingKaomojiCandidateItems(expanded: isCandidateExpanded)
        } else {
            pendingItems = nil
        }
        accumulatedCandidates = (pendingItems ?? CandidateBarDataSource.candidateItems(from: controller)).filter {
            $0.kind != .placeholder
        }
        candidateSnapshotGeneration += 1
        candidateSnapshotCompositionRevision = controller.state.compositionRevision
        candidateSnapshotRawInput = controller.state.lastRimeOutput?.rawInput ?? controller.state.currentComposition
        nextCandidateGlobalIndex = nextGlobalIndexAfterCurrentItems()
        hasMoreCandidates = controller.state.lastRimeOutput?.hasMorePages ?? false
        isLoadingMoreCandidates = false
        deferredCandidatePrefetchMode = nil
        candidatePrefetchRequestSerial += 1
        candidateCellSizeCache.removeAll(keepingCapacity: true)
        candidatePageDepth = 0
        candidatePrefetchMode = isCandidateExpanded ? .expanded : .bar
    }

    /// Publish candidates from a captured T9 composition snapshot (same revision as Path Bar).
    func resetCandidateSnapshot(from snapshot: T9CompositionPresentationSnapshot) {
        // Prefer snapshot-owned paging fields; do not re-read live controller for
        // page identity when the snapshot already captured them.
        let preedit =
            !snapshot.compositionPreedit.isEmpty
            ? snapshot.compositionPreedit
            : snapshot.visiblePreedit
        let items: [CandidateItem]
        if !preedit.isEmpty || !snapshot.candidates.isEmpty {
            items = CandidateBarDataSource.candidateItems(
                from: controller,
                rimeCandidates: snapshot.candidates,
                preeditText: preedit.isEmpty ? " " : preedit,
                pageNumber: snapshot.candidatePageNumber
            )
        } else {
            items = CandidateBarDataSource.candidateItems(from: controller)
        }
        accumulatedCandidates = items.filter { $0.kind != .placeholder }
        candidateSnapshotGeneration += 1
        candidateSnapshotCompositionRevision = snapshot.revision
        candidateSnapshotRawInput =
            snapshot.rimeRawInput
            ?? controller.state.currentComposition
        nextCandidateGlobalIndex = nextGlobalIndexAfterCurrentItems()
        hasMoreCandidates = snapshot.hasMorePages
        isLoadingMoreCandidates = false
        deferredCandidatePrefetchMode = nil
        candidatePrefetchRequestSerial += 1
        candidateCellSizeCache.removeAll(keepingCapacity: true)
        candidatePageDepth = 0
        candidatePrefetchMode = isCandidateExpanded ? .expanded : .bar
    }
}

import KeyboardCore
import UIKit

extension KeyboardViewController {
    @objc func insertKey(_ sender: UIButton) {
        // T9 letter-group keys show `ABC` etc. but must send the digit identity to RIME.
        let key: String
        if sender.accessibilityValue == KeyboardViewController.t9DigitAccessibilityValue,
            let digit = sender.accessibilityIdentifier,
            !digit.isEmpty
        {
            key = digit
        } else {
            key =
                sender.title(for: .normal)
                ?? sender.accessibilityIdentifier
                ?? ""
        }
        guard !key.isEmpty else { return }
        #if DEBUG && KEYBOARD_WAKE_OWNER_PROBE
            let wakeAttempt = KeyboardWakeOwnerProbe.shared.beginAttempt(appearanceOrdinal: wakeProbeAppearanceOrdinal)
            recordWakeOwnerProbe(.insertBegin)
            defer {
                recordWakeOwnerProbe(.insertEnd)
                if let wakeAttempt { KeyboardWakeOwnerProbe.shared.endAttempt(wakeAttempt) }
            }
        #endif
        let startTime = CACurrentMediaTime()
        inputEventSequence += 1
        let eventID = inputEventSequence
        let compositionLengthBefore = controller.state.currentComposition.count
        #if DEBUG || T9_AUTO_ANCHOR_DEVICE_PREFLIGHT
            // Segmented sample for continuous T9 digit typing (no Path/candidate pick).
            // Privacy: lengths only — never log the digit sequence itself.
            let shouldSampleT9Segments =
                controller.usesT9InputSemantics
                && key.count == 1
                && key.first?.isNumber == true
            if shouldSampleT9Segments {
                #if T9_AUTO_ANCHOR_DEVICE_PREFLIGHT
                    recordDevicePreflightExecutionGeometryBeforeFirstT9Key()
                #endif
                HotPathSegmentTiming.beginKey(
                    eventID: UInt64(eventID),
                    keyLength: key.count,
                    compositionLengthBefore: compositionLengthBefore,
                    session: controller.rimeEngine?.diagnosticSessionSnapshot
                )
            }
        #endif

        #if DEBUG
            let idleMs = lastInputCompletionTime.map { (startTime - $0) * 1000 }
            Logger.shared.debug(
                "KEY BEGIN #\(eventID) keyLength=\(key.count) idleMs=\(idleMs.map { String(format: "%.1f", $0) } ?? "first") "
                    + "compositionLength=\(compositionLengthBefore)",
                category: .performance
            )

            let identifier = ObjectIdentifier(sender)
            if let touchDownTime = keyTouchDownTimes.removeValue(forKey: identifier) {
                let delay = (startTime - touchDownTime) * 1000
                Logger.shared.performance(
                    "insertKey enter after keyDown (\(String(format: "%.1f", delay))ms)"
                )
            } else {
                Logger.shared.performance("insertKey enter without keyDown timestamp")
            }
        #endif

        emitKeyPressFeedbackIfNeeded(for: sender)

        let handleStartTime = CACurrentMediaTime()
        let effects = controller.handle(.insertKey(key))
        let handleMs = (CACurrentMediaTime() - handleStartTime) * 1000
        #if DEBUG || T9_AUTO_ANCHOR_DEVICE_PREFLIGHT
            if shouldSampleT9Segments {
                HotPathSegmentTiming.noteResult(
                    rawLength: controller.state.lastRimeOutput?.rawInput?.count
                        ?? controller.state.currentComposition.count,
                    pathCount: controller.state.t9PinyinPathState.compactPaths.count,
                    candidateCount: controller.state.lastRimeOutput?.candidates.count ?? 0,
                    didCommit: controller.state.lastRimeOutput?.committedText != nil,
                    session: controller.rimeEngine?.diagnosticSessionSnapshot
                )
                #if DEBUG
                    let shadow = controller.t9ShadowAnchorObservation()
                    Logger.shared.debug(
                        "T9SHADOW #\(eventID) status=\(shadow.status.rawValue) "
                            + "generation=\(shadow.rawInputGeneration) "
                            + "provenance=\(shadow.provenanceRevision) "
                            + "candidates=\(shadow.candidateCount) "
                            + "compatible=\(shadow.compatibleCandidateCount) "
                            + "uniquePaths=\(shadow.uniqueCompatiblePathCount) "
                            + "rejected=\(shadow.rejectedCandidateCount) "
                            + "commonSyllables=\(shadow.observedCommonSyllableCount) "
                            + "closedSyllables=\(shadow.closedCommonSyllableCount) "
                            + "anchorSlots=\(shadow.anchorSlotCount) "
                            + "unresolvedSlots=\(shadow.unresolvedSlotCount) "
                            + "complete=\(shadow.evidenceComplete)",
                        category: .performance
                    )
                    if let retryShadow = controller.t9AutoAnchorRetryShadowObservation() {
                        Logger.shared.debug(
                            "T9RETRYSHADOW #\(eventID) "
                                + "status=\(retryShadow.status.rawValue) "
                                + "sourceSlots=\(retryShadow.sourceDigitCount) "
                                + "rejectedAt=\(retryShadow.rejectedAtSourceDigitCount) "
                                + "candidates=\(retryShadow.candidateCount) "
                                + "anchorSlots=\(retryShadow.anchoredSlotCount) "
                                + "unresolvedSlots=\(retryShadow.unresolvedSlotCount)",
                            category: .performance
                        )
                    }
                #endif
            }
            #if DEBUG
                Logger.shared.debug(
                    "KEY ENGINE END #\(eventID) durationMs=\(String(format: "%.1f", handleMs)) "
                        + "candidates=\(controller.state.lastRimeOutput?.candidates.count ?? 0)",
                    category: .performance
                )
            #endif
        #endif

        let uiStartTime = CACurrentMediaTime()
        syncUI(with: effects)
        let endTime = CACurrentMediaTime()
        let uiMs = (endTime - uiStartTime) * 1000
        let totalMs = (endTime - startTime) * 1000
        #if DEBUG
            lastInputCompletionTime = endTime
            Logger.shared.performance(
                "KEY END #\(eventID) keyLength=\(key.count) total=\(String(format: "%.1f", totalMs))ms "
                    + "engine=\(String(format: "%.1f", handleMs))ms ui=\(String(format: "%.1f", uiMs))ms"
            )
        #endif
        #if DEBUG || T9_AUTO_ANCHOR_DEVICE_PREFLIGHT
            if shouldSampleT9Segments {
                HotPathSegmentTiming.endKey(
                    totalMs: totalMs,
                    engineMs: handleMs,
                    uiMs: uiMs
                )
            }
        #endif
        // Track T9 digit cadence for bar-prefetch idle gating (release + debug).
        if controller.usesT9InputSemantics,
            key.count == 1,
            key.first?.isNumber == true
        {
            lastT9DigitKeyTime = endTime
        }
        if totalMs >= 50 {
            Logger.shared.warning(
                "SLOW KEY #\(eventID) keyLength=\(key.count) total=\(String(format: "%.1f", totalMs))ms "
                    + "engine=\(String(format: "%.1f", handleMs))ms ui=\(String(format: "%.1f", uiMs))ms",
                category: .performance
            )
        }
    }

    @objc func insertCandidate(_ sender: UIButton) {
        guard
            let candidate = sender.configuration?.title,
            let kind = CandidateKind(rawValue: sender.tag)
        else { return }
        emitKeyPressFeedbackIfNeeded(for: sender)
        let effects = controller.handle(.insertCandidate(candidate, kind: kind))
        syncUI(with: effects)
    }

    @objc func insertDirectText(_ sender: UIButton) {
        guard let text = sender.title(for: .normal) else { return }
        emitKeyPressFeedbackIfNeeded(for: sender)
        let effects = controller.handle(.insertDirectText(text))
        syncUI(with: effects)
    }

    @objc func insertSmartDoubleQuote(_ sender: UIButton) {
        emitKeyPressFeedbackIfNeeded(for: sender)
        let quote = nextSmartDoubleQuote(contextBeforeInput: textDocumentProxy.documentContextBeforeInput)
        let effects = controller.handle(.insertDirectText(quote))
        syncUI(with: effects)
    }

    private func nextSmartDoubleQuote(contextBeforeInput: String?) -> String {
        guard let contextBeforeInput, !contextBeforeInput.isEmpty else { return "“" }

        let openingCount = contextBeforeInput.filter { $0 == "“" }.count
        let closingCount = contextBeforeInput.filter { $0 == "”" }.count

        // 第一次输入左引号；如果已有未闭合的左引号，下一次输入右引号。
        // 一旦左右引号都被删除，光标前不再包含它们，下一次又会回到左引号。
        if openingCount == 0 && closingCount == 0 { return "“" }
        if openingCount > closingCount { return "”" }
        return "”"
    }

    @objc func insertEmoji(_ sender: UIButton) {
        guard let emoji = sender.title(for: .normal) else { return }
        emitKeyPressFeedbackIfNeeded(for: sender)
        let effects = controller.handle(.insertEmoji(emoji))
        syncUI(with: effects)
    }
}

import KeyboardCore
import UIKit

extension KeyboardViewController {
    #if DEBUG
        /// Correlates a UIKit pointer terminal with lifecycle/candidate state.
        /// `role` is deliberately coarse so diagnostics never record a typed key.
        func recordKeyboardTrackingDiagnostic(
            button: KeyboardKeyButton,
            phase: KeyboardKeyTrackingPhase
        ) {
            #if KEYBOARD_WAKE_OWNER_PROBE
                wakeOwnerProbeTouch(ObjectIdentifier(button), began: phase == .began)
            #endif
            let role: String
            if button === shiftButton {
                role = "shift"
            } else if button === returnButton {
                role = "return"
            } else if button === nextKeyboardButton {
                role = "nextKeyboard"
            } else if button === t9SpaceButton {
                role = "space"
            } else {
                switch button.visualStyle {
                case .character:
                    role = "character"
                case .function:
                    role = "function"
                case .space:
                    role = "space"
                case .returnKey:
                    role = "return"
                case .active:
                    role = "active"
                }
            }
            Logger.shared.info(
                "KBDVIS touch phase=\(phase.rawValue) role=\(role) "
                    + "pressed=\(keyPressFeedbackEmittedButtonIDs.count)",
                category: .display
            )
            guard isHighFidelityDiagnosticsActive else { return }
            diagnosticsJournal.record(
                code: .touchTerminal,
                category: .display,
                appearanceID: diagnosticsAppearanceID,
                fields: [
                    .count(.highlightedKeyCount, keyPressFeedbackEmittedButtonIDs.count),
                    .flag(.isKeyHighlighted, phase == .began),
                ]
            )
        }

        /// Snapshot only structural state needed to separate stale UIKit paint,
        /// real key tracking, Core composition and lifecycle cleanup. No key text,
        /// candidate text or host-document text is emitted.
        func recordKeyboardVisualDiagnostic(
            _ marker: String,
            effects: KeyboardEffect? = nil
        ) {
            guard controller != nil else { return }
            let output = controller.state.lastRimeOutput
            let collectionItems = candidateCollectionView?.numberOfItems(inSection: 0) ?? 0
            let visibleCells = candidateCollectionView?.visibleCells.count ?? 0
            let ownerEpoch = controller.threadAffineRimeCoordinator?.diagnostics.sessionEpoch ?? 0
            let effectsRawValue = effects.map { String($0.rawValue) } ?? "none"
            Logger.shared.info(
                "KBDVIS marker=\(marker) effects=\(effectsRawValue) "
                    + "appeared=\(hasViewAppeared ? 1 : 0) "
                    + "ui=\(isKeyboardUIInstalled ? 1 : 0) "
                    + "ownerReady=\(controller.threadAffineRimeCoordinator?.isOwnerReady == true ? 1 : 0) "
                    + "epoch=\(ownerEpoch) "
                    + "pressed=\(keyPressFeedbackEmittedButtonIDs.count) "
                    + "compositionLength=\(controller.state.currentComposition.count) "
                    + "rawLength=\(output?.rawInput?.count ?? 0) "
                    + "coreCandidates=\(output?.candidates.count ?? 0) "
                    + "cachedCandidates=\(accumulatedCandidates.count) "
                    + "collectionItems=\(collectionItems) visibleCells=\(visibleCells) "
                    + "generation=\(candidateSnapshotGeneration) "
                    + "revision=\(controller.state.compositionRevision)",
                category: .display
            )
            guard isHighFidelityDiagnosticsActive else { return }
            diagnosticsJournal.record(
                code: .candidateVisibilityChanged,
                category: .display,
                appearanceID: diagnosticsAppearanceID,
                fields: [
                    .count(.candidateCount, output?.candidates.count ?? 0),
                    .count(.visibleCandidateCellCount, visibleCells),
                    .count(.highlightedKeyCount, keyPressFeedbackEmittedButtonIDs.count),
                    .count(.revision, Int(clamping: controller.state.compositionRevision)),
                    .count(.sessionEpoch, Int(clamping: ownerEpoch)),
                    .flag(.isCandidateBarVisible, collectionItems > 0),
                    .flag(.isHighFidelityEnabled, true),
                ]
            )
        }
    #endif

    /// Records touch timing and responds synchronously so rapid typing receives immediate feedback.
    @objc func keyTouchDown(_ sender: UIButton) {
        let identifier = ObjectIdentifier(sender)
        #if DEBUG
            keyTouchDownTimes[identifier] = CACurrentMediaTime()
        #endif
        keyPressFeedbackEmittedButtonIDs.insert(identifier)

        #if DEBUG
            Logger.shared.performance("keyDown registered")
        #endif

        sender.backgroundColor = highlightedKeyColor
        sender.transform = CGAffineTransform(scaleX: 0.96, y: 0.96)
        emitKeyPressFeedback()
    }

    @objc func keyTouchUp(_ sender: UIButton) {
        keyPressFeedbackEmittedButtonIDs.remove(ObjectIdentifier(sender))
        restoreKeyAppearance(sender)
    }

    func restoreKeyAppearance(_ sender: UIButton) {
        let restore = {
            sender.transform = .identity

            if sender === self.shiftButton {
                self.updateShiftButtonAppearance()
                return
            }

            guard let style = self.keyStyle(for: sender) else {
                sender.backgroundColor = self.characterKeyColor
                return
            }
            sender.backgroundColor = self.backgroundForStyle(style)
        }

        guard !UIAccessibility.isReduceMotionEnabled else {
            restore()
            return
        }

        UIView.animate(
            withDuration: 0.25,
            delay: 0,
            usingSpringWithDamping: 0.6,
            initialSpringVelocity: 0,
            options: [.allowUserInteraction, .beginFromCurrentState],
            animations: restore,
            completion: nil
        )
    }

    func resetAllKeyPressVisualState() {
        keyTouchDownTimes.removeAll()
        keyPressFeedbackEmittedButtonIDs.removeAll()
        restoreButtons(in: view)
    }

    private func restoreButtons(in root: UIView?) {
        guard let root else { return }
        if let button = root as? UIButton {
            UIView.performWithoutAnimation {
                button.transform = .identity
                if button === shiftButton {
                    updateShiftButtonAppearance()
                } else if let style = keyStyle(for: button) {
                    button.backgroundColor = backgroundForStyle(style)
                }
            }
        }

        for subview in root.subviews {
            restoreButtons(in: subview)
        }
    }
}

