//
//  KeyboardHostLifecycleRecoveryGate.swift
//  Keyboard
//
//  MainActor 内存状态机：宿主失活/重新激活与展示世代的恢复决策。
//  无 UIKit / KeyboardCore / I/O 依赖；不持有引擎或 composition。
//  许可判定由调用方在任何可能创建 owner 的动作之前传入。
//

/// Opaque identity for the current `NSExtensionContext` without importing UIKit.
struct KeyboardHostExtensionContextID: Hashable, Sendable {
    private let objectID: ObjectIdentifier

    init(_ object: AnyObject) {
        objectID = ObjectIdentifier(object)
    }
}

enum KeyboardHostRecoveryPhase: Equatable, Sendable {
    case hidden
    case appearing
    case visible
}

enum KeyboardHostRecoveryAction: Equatable, Sendable {
    case none
    case suspendRuntime
    case performSharedResume
    case rearmFirstFrameGate
    case completeFirstFrameActivation
}

enum KeyboardHostRecoverySource: Equatable, Sendable {
    case appearance
    case hostActive
    case firstFrame
}

/// One-shot UI classification of Core canary state. The gate does not store or mutate Core.
enum KeyboardHostRecoveryCanaryPermission: Equatable, Sendable {
    case nonCanaryBuild
    case baselineActive
    case visibilitySuspended(resumeGranted: Bool)
    case canaryStarting
    case canaryActive
    case visibilityEnding
    case fenceIssued
    case baselineRecoveryPermitted
    case fencedUnavailable

    func permitsOwnerStarting(source: KeyboardHostRecoverySource) -> Bool {
        switch self {
        case .nonCanaryBuild, .baselineActive:
            return true
        case .visibilitySuspended(let granted):
            return granted
        case .canaryStarting:
            // Original first-frame startup owns canaryStarting; host-active must not start a second owner.
            return source == .firstFrame
        case .canaryActive, .visibilityEnding, .fenceIssued, .fencedUnavailable,
            .baselineRecoveryPermitted:
            return false
        }
    }

    /// Host-active must not rearm or resume when first-frame creation or generic resume is forbidden.
    var blocksHostActiveRecovery: Bool {
        switch self {
        case .fenceIssued, .visibilityEnding, .fencedUnavailable, .baselineRecoveryPermitted,
            .canaryActive:
            return true
        case .visibilitySuspended(let granted):
            return !granted
        case .canaryStarting, .nonCanaryBuild, .baselineActive:
            return false
        }
    }
}

/// Pending host-suspend request, consumed at most once per generation/context pair.
struct KeyboardHostPendingSuspend: Equatable, Sendable {
    var generation: UInt64
    var context: KeyboardHostExtensionContextID
    var activatedAtSuspend: Bool
    var blocked: Bool
}

@MainActor
final class KeyboardHostLifecycleRecoveryGate {
    private(set) var presentationGeneration: UInt64 = 0
    private(set) var phase: KeyboardHostRecoveryPhase = .hidden
    private(set) var currentContext: KeyboardHostExtensionContextID?
    private(set) var pending: KeyboardHostPendingSuspend?
    private(set) var firstFrameRearmPending = false
    private(set) var didSuspendCurrentGeneration = false
    private(set) var firstFrameConsumedForGeneration = false
    private(set) var firstFrameArmToken: UInt64 = 0
    private(set) var firstFrameArmGeneration: UInt64 = 0
    private(set) var firstFrameTickCount = 0
    private(set) var hasLiveFirstFrameArm = false
    /// After reject/complete, begin must not mint a new token until rearm or a new presentation.
    private var firstFrameArmSuppressed = false

    var hasVisibleResumePending: Bool {
        guard let pending, !pending.blocked else { return false }
        return pending.generation == presentationGeneration && pending.context == currentContext
    }

    func noteViewWillAppear(context: KeyboardHostExtensionContextID?) {
        presentationGeneration &+= 1
        phase = .appearing
        currentContext = context
        pending = nil
        firstFrameRearmPending = false
        didSuspendCurrentGeneration = false
        firstFrameConsumedForGeneration = false
        firstFrameArmSuppressed = false
        invalidateFirstFrameArm()
    }

    func noteViewDidAppear(hasWindow: Bool) {
        guard phase == .appearing else { return }
        if hasWindow {
            phase = .visible
        }
        didSuspendCurrentGeneration = false
    }

    func noteViewWillDisappear() {
        phase = .hidden
        presentationGeneration &+= 1
        pending = nil
        firstFrameRearmPending = false
        didSuspendCurrentGeneration = false
        firstFrameConsumedForGeneration = false
        firstFrameArmSuppressed = true
        invalidateFirstFrameArm()
    }

    @discardableResult
    func handleHostWillResignActive(
        context: KeyboardHostExtensionContextID?,
        activatedAtSuspend: Bool
    ) -> KeyboardHostRecoveryAction {
        guard let context, context == currentContext else { return .none }
        let hadRearm = firstFrameRearmPending
        firstFrameRearmPending = false
        invalidateFirstFrameArm()
        if didSuspendCurrentGeneration {
            // Duplicate resign must still cancel an armed first-frame wait.
            return hadRearm ? .suspendRuntime : .none
        }
        didSuspendCurrentGeneration = true
        if phase == .visible, let currentContext {
            pending = KeyboardHostPendingSuspend(
                generation: presentationGeneration,
                context: currentContext,
                activatedAtSuspend: activatedAtSuspend,
                blocked: false
            )
        } else {
            // Appearing/hidden resign must not create a visible resume pending.
            pending = nil
        }
        return .suspendRuntime
    }

    func previewHostDidBecomeActive(
        context: KeyboardHostExtensionContextID?,
        hasWindow: Bool
    ) -> KeyboardHostRecoveryAction {
        decideHostDidBecomeActive(context: context, hasWindow: hasWindow)
    }

    @discardableResult
    func handleHostDidBecomeActive(
        context: KeyboardHostExtensionContextID?,
        hasWindow: Bool,
        canary: KeyboardHostRecoveryCanaryPermission
    ) -> KeyboardHostRecoveryAction {
        let action = decideHostDidBecomeActive(context: context, hasWindow: hasWindow)
        switch action {
        case .none:
            return .none
        case .performSharedResume:
            if !canary.permitsOwnerStarting(source: .hostActive) {
                blockPending()
                return .none
            }
            consumePendingAndRearm()
            return .performSharedResume
        case .rearmFirstFrameGate:
            if canary.blocksHostActiveRecovery {
                blockPending()
                return .none
            }
            invalidateFirstFrameArm()
            firstFrameArmSuppressed = false
            firstFrameRearmPending = true
            firstFrameConsumedForGeneration = false
            return .rearmFirstFrameGate
        case .suspendRuntime, .completeFirstFrameActivation:
            return .none
        }
    }

    /// Issues or reuses the current first-frame arm. Hidden / no-window never mint a token.
    @discardableResult
    func beginFirstFrameArm(hasWindow: Bool) -> UInt64? {
        guard phase == .visible, hasWindow else {
            if hasLiveFirstFrameArm {
                firstFrameArmSuppressed = true
                invalidateFirstFrameArm()
            }
            return nil
        }
        if hasLiveFirstFrameArm {
            return firstFrameArmToken
        }
        if firstFrameArmSuppressed { return nil }
        if firstFrameConsumedForGeneration, !firstFrameRearmPending { return nil }
        firstFrameArmToken &+= 1
        if firstFrameArmToken == 0 {
            firstFrameArmToken = 1
        }
        firstFrameArmGeneration = presentationGeneration
        firstFrameTickCount = 0
        hasLiveFirstFrameArm = true
        return firstFrameArmToken
    }

    func invalidateFirstFrameArm() {
        hasLiveFirstFrameArm = false
        firstFrameTickCount = 0
    }

    func previewFirstFrameTick(
        token: UInt64,
        generation: UInt64,
        hasWindow: Bool
    ) -> KeyboardHostRecoveryAction {
        guard isLiveArm(token: token, generation: generation) else { return .none }
        guard phase == .visible, hasWindow else { return .none }
        guard firstFrameTickCount + 1 >= 2 else { return .none }
        return decideFirstFrameElapsed(hasWindow: hasWindow)
    }

    @discardableResult
    func noteFirstFrameTick(
        token: UInt64,
        generation: UInt64,
        hasWindow: Bool,
        canary: KeyboardHostRecoveryCanaryPermission
    ) -> KeyboardHostRecoveryAction {
        guard isLiveArm(token: token, generation: generation) else { return .none }
        if phase != .visible || !hasWindow {
            rejectCurrentArm(blockPending: false)
            return .none
        }
        firstFrameTickCount += 1
        if firstFrameTickCount < 2 {
            return .none
        }
        let action = decideFirstFrameElapsed(hasWindow: hasWindow)
        guard action == .completeFirstFrameActivation else {
            rejectCurrentArm(blockPending: false)
            return .none
        }
        if !canary.permitsOwnerStarting(source: .firstFrame) {
            rejectCurrentArm(blockPending: true)
            return .none
        }
        consumePendingAndRearm()
        firstFrameConsumedForGeneration = true
        firstFrameArmSuppressed = true
        invalidateFirstFrameArm()
        return .completeFirstFrameActivation
    }

    /// Same recovery branch as host-active, used when active arrived before the window existed.
    @discardableResult
    func handleVisibleWindowEstablished(
        hasWindow: Bool,
        canary: KeyboardHostRecoveryCanaryPermission
    ) -> KeyboardHostRecoveryAction {
        handleHostDidBecomeActive(
            context: currentContext,
            hasWindow: hasWindow,
            canary: canary
        )
    }

    private func isLiveArm(token: UInt64, generation: UInt64) -> Bool {
        hasLiveFirstFrameArm && token == firstFrameArmToken && generation == firstFrameArmGeneration
    }

    private func rejectCurrentArm(blockPending shouldBlock: Bool) {
        firstFrameArmSuppressed = true
        if shouldBlock {
            blockPending()
        } else {
            invalidateFirstFrameArm()
        }
    }

    private func decideHostDidBecomeActive(
        context: KeyboardHostExtensionContextID?,
        hasWindow: Bool
    ) -> KeyboardHostRecoveryAction {
        guard let context, context == currentContext else { return .none }
        guard phase == .visible, hasWindow else { return .none }
        guard let pending, !pending.blocked else { return .none }
        guard pending.generation == presentationGeneration, pending.context == context else {
            return .none
        }
        if firstFrameRearmPending {
            return .none
        }
        if pending.activatedAtSuspend {
            return .performSharedResume
        }
        return .rearmFirstFrameGate
    }

    private func decideFirstFrameElapsed(hasWindow: Bool) -> KeyboardHostRecoveryAction {
        guard phase == .visible, hasWindow else { return .none }
        if firstFrameConsumedForGeneration, !firstFrameRearmPending {
            return .none
        }
        if let pending {
            guard !pending.blocked else { return .none }
            guard pending.generation == presentationGeneration, pending.context == currentContext
            else {
                return .none
            }
        }
        return .completeFirstFrameActivation
    }

    private func blockPending() {
        pending?.blocked = true
        firstFrameRearmPending = false
        firstFrameArmSuppressed = true
        invalidateFirstFrameArm()
    }

    private func consumePendingAndRearm() {
        pending = nil
        firstFrameRearmPending = false
        didSuspendCurrentGeneration = false
    }
}

import KeyboardCore
import UIKit

/// 展开按钮视觉上只显示 chevron，但真实命中范围略大。
/// iOS Keyboard Extension 中完全透明的区域可能不稳定，保留不可见 backing 来承接点击和下滑。
private final class CandidateBarExpandButton: UIButton {
    var hitOutsets = UIEdgeInsets(top: 10, left: 16, bottom: 12, right: 12)

    override func point(inside point: CGPoint, with event: UIEvent?) -> Bool {
        guard isUserInteractionEnabled, !isHidden, alpha > 0.01 else { return false }
        return expandedHitBounds.contains(point)
    }

    var expandedHitBounds: CGRect {
        bounds.inset(
            by: UIEdgeInsets(
                top: -hitOutsets.top,
                left: -hitOutsets.left,
                bottom: -hitOutsets.bottom,
                right: -hitOutsets.right
            )
        )
    }
}

#if DEBUG
    @MainActor
    protocol CandidateTouchDiagnosticSink: AnyObject {
        func recordCandidateTouchRouted(
            band: DiagnosticEvent.CandidateTouchBand,
            didHitCell: Bool
        )
        func recordCandidateGestureTerminal(didBegin: Bool, wasCancelled: Bool)
    }
#endif

/// The horizontal candidate bar container.
///
/// The fixed height and expand-button width are part of the keyboard presentation
/// baseline: changing them can reintroduce keyboard resize/flicker regressions.
/// Isolated from `CandidateBarView`'s `@MainActor` so optional delegate
/// methods actually bind. Putting them on the bar only "nearly matches".
private final class CandidateBarGestureBridge: NSObject, UIGestureRecognizerDelegate {
    weak var itemTap: UIGestureRecognizer?
    weak var swipeDown: UIGestureRecognizer?
    weak var horizontalFallback: UIGestureRecognizer?
    weak var collectionPan: UIGestureRecognizer?
    #if DEBUG && KEYBOARD_WAKE_OWNER_PROBE
        weak var wakeProbeButton: UIButton?
        func gestureRecognizer(_ gestureRecognizer: UIGestureRecognizer, shouldReceive touch: UITouch) -> Bool {
            guard let button = wakeProbeButton, let touched = touch.view else { return true }
            return !touched.isDescendant(of: button)
        }
    #endif

    func gestureRecognizer(
        _ gestureRecognizer: UIGestureRecognizer,
        shouldRecognizeSimultaneouslyWith otherGestureRecognizer: UIGestureRecognizer
    ) -> Bool {
        if gestureRecognizer === itemTap || otherGestureRecognizer === itemTap {
            return true
        }
        if gestureRecognizer === horizontalFallback || otherGestureRecognizer === horizontalFallback {
            return false
        }
        guard gestureRecognizer === swipeDown || otherGestureRecognizer === swipeDown else {
            return false
        }
        return gestureRecognizer === collectionPan || otherGestureRecognizer === collectionPan
    }

    func gestureRecognizer(
        _ gestureRecognizer: UIGestureRecognizer,
        shouldRequireFailureOf otherGestureRecognizer: UIGestureRecognizer
    ) -> Bool {
        if gestureRecognizer === itemTap,
            otherGestureRecognizer === swipeDown || otherGestureRecognizer === horizontalFallback
        {
            return false
        }
        return false
    }
}

@MainActor
final class CandidateBarView: UIView {
    private enum Layout {
        /// Keeps candidate text visually settled in the thinner bar.
        static let verticalTextInset: CGFloat = 0
        /// Hit area is intentionally larger than the visible chevron for reliable touch.
        static let expandButtonTouchSize: CGFloat = 56
        static let expandButtonVerticalAlignmentOffset: CGFloat = 9
    }

    let collectionView: CandidateCollectionView
    let expandButton: UIButton
    let expandButtonWidthConstraint: NSLayoutConstraint
    private var candidateTrailingConstraint: NSLayoutConstraint!
    #if DEBUG && KEYBOARD_WAKE_OWNER_PROBE
        private var wakeProbeButton: UIButton?
        private var wakeProbeTrailingConstraint: NSLayoutConstraint?
        var onWakeOwnerProbeTouch: ((ObjectIdentifier, Bool) -> Void)?
    #endif
    /// Swipe-down expands only in expand mode (`PD-CANDIDATE-BAR-IDLE-DISMISS-001`).
    var allowsSwipeToExpand = false
    private weak var expandActionTarget: NSObject?
    private let expandAction: Selector
    private let itemTapRecognizer = UITapGestureRecognizer()
    private let gestureBridge = CandidateBarGestureBridge()
    private let candidateBarHeight: CGFloat
    private let bottomHitExtension: CGFloat
    private var swipeDownRecognizer: UIPanGestureRecognizer?
    private var horizontalFallbackRecognizer: UIPanGestureRecognizer?
    private var hasTriggeredSwipeDownExpand = false
    private var isSwipeDownTracking = false
    private var swipePreviewIndexPath: IndexPath?
    private var horizontalFallbackStartOffsetX: CGFloat = 0
    private var lastPointInsideDiagnosticLogTime: CFTimeInterval = 0
    private var lastHitTestDiagnosticLogTime: CFTimeInterval = 0
    private var lastFallbackPanDiagnosticLogTime: CFTimeInterval = 0
    #if DEBUG
        /// Passive observation only. The callback runs after UIKit has resolved the
        /// same hit view that would have been returned without diagnostics.
        private weak var diagnosticSink: CandidateTouchDiagnosticSink?
        private weak var lastStructuredTouch: UITouch?
        private var expandHitboxOverlay: DebugKeyTouchRangeOverlayView?
        private var hitProbeLabel: UILabel?
    #endif

    init(
        height: CGFloat,
        bottomHitExtension: CGFloat,
        backgroundColor: UIColor,
        interactionTarget: Any?,
        expandAction: Selector
    ) {
        self.expandActionTarget = interactionTarget as? NSObject
        self.expandAction = expandAction
        self.candidateBarHeight = height
        self.bottomHitExtension = bottomHitExtension

        let layout = UICollectionViewFlowLayout()
        layout.scrollDirection = .horizontal
        // 候选之间不能留下真实 layout 空隙，否则手势会从 scroll view 的非 cell 区域启动。
        // 视觉间距由 cell 自身宽度承担，保证横滑和下滑都能命中候选列表。
        layout.minimumLineSpacing = 0
        layout.minimumInteritemSpacing = 0
        layout.sectionInset = UIEdgeInsets(top: Layout.verticalTextInset, left: 4, bottom: 0, right: 8)

        collectionView = CandidateCollectionView(frame: .zero, collectionViewLayout: layout)
        expandButton = Self.makeExpandButton(target: interactionTarget, action: expandAction)
        expandButtonWidthConstraint = expandButton.widthAnchor.constraint(equalToConstant: Layout.expandButtonTouchSize)

        super.init(frame: .zero)

        #if DEBUG
            diagnosticSink = interactionTarget as? CandidateTouchDiagnosticSink
            collectionView.onCandidateGestureTerminal = { [weak self] didBegin, wasCancelled in
                self?.diagnosticSink?.recordCandidateGestureTerminal(
                    didBegin: didBegin,
                    wasCancelled: wasCancelled
                )
            }
        #endif

        self.backgroundColor = backgroundColor
        isOpaque = false
        layer.cornerRadius = 0
        clipsToBounds = false

        configureCollectionView()
        addSubview(collectionView)
        addSubview(expandButton)
        gestureBridge.collectionPan = collectionView.panGestureRecognizer
        installItemTapGesture()
        installHorizontalFallbackGesture()
        installSwipeDownExpandGesture()

        candidateTrailingConstraint = collectionView.trailingAnchor.constraint(
            equalTo: expandButton.leadingAnchor, constant: -2)
        NSLayoutConstraint.activate([
            expandButton.trailingAnchor.constraint(equalTo: trailingAnchor, constant: -3),
            expandButton.centerYAnchor.constraint(
                equalTo: topAnchor,
                constant: height / 2 + Layout.expandButtonVerticalAlignmentOffset
            ),
            expandButtonWidthConstraint,
            expandButton.heightAnchor.constraint(equalToConstant: Layout.expandButtonTouchSize),

            collectionView.leadingAnchor.constraint(equalTo: leadingAnchor, constant: 2),
            candidateTrailingConstraint,
            collectionView.topAnchor.constraint(equalTo: topAnchor),
            collectionView.bottomAnchor.constraint(equalTo: bottomAnchor),

            heightAnchor.constraint(equalToConstant: height + bottomHitExtension),
        ])
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("init(coder:) has not been implemented")
    }

    /// True while a downward expand pan is recognized. Callers should skip
    /// `didSelect` so a swipe-to-expand does not also commit the cell.
    var shouldSuppressCandidateSelection: Bool {
        isSwipeDownTracking || hasTriggeredSwipeDownExpand
    }

    /// Direct tap delivery. UICollectionView's own selection tap waits for the
    /// bar's expand pan to fail and never fires for a stationary press.
    var onItemTap: ((IndexPath) -> Void)?

    override func layoutSubviews() {
        super.layoutSubviews()
        #if DEBUG
            refreshDebugHitboxOverlay()
        #endif
    }

    #if DEBUG
        func refreshDebugHitboxOverlay() {
            for case let cell as CandidateCollectionCell in collectionView.visibleCells {
                cell.refreshDebugHitboxOverlay()
            }
            guard DebugHitboxOverlayPresentation.isShowing else {
                expandHitboxOverlay?.isHidden = true
                hitProbeLabel?.isHidden = true
                return
            }
            if !expandButton.isHidden {
                let overlay = expandHitboxOverlay ?? DebugKeyTouchRangeOverlayView()
                if expandHitboxOverlay == nil {
                    addSubview(overlay)
                    expandHitboxOverlay = overlay
                }
                overlay.isHidden = false
                overlay.apply(
                    touchFrame: expandedButtonHitFrame,
                    visualFrame: expandButton.frame,
                    in: self
                )
                bringSubviewToFront(overlay)
            } else {
                expandHitboxOverlay?.isHidden = true
            }
            DebugHitboxOverlayPresentation.refreshProbeLabel = { [weak self] in
                self?.refreshHitProbeLabel(text: DebugHitboxOverlayPresentation.probeLine)
            }
            refreshHitProbeLabel(text: DebugHitboxOverlayPresentation.probeLine)
        }

        private func recordHitProbe(point: CGPoint, hitView: UIView?) {
            guard DebugHitboxOverlayPresentation.isShowing else { return }
            let collectionPoint = collectionView.convert(point, from: self)
            let index = collectionView.indexPathForItem(at: collectionPoint)
            let cell = index.flatMap { collectionView.cellForItem(at: $0) as? CandidateCollectionCell }
            let contentHeight = cell.map { Int($0.contentView.bounds.height) } ?? -1
            let cellHeight = cell.map { Int($0.bounds.height) } ?? -1
            let hitName = CandidateTouchDiagnostics.viewPath(hitView)
            let indexText = index.map { String($0.item) } ?? "nil"
            let inCell: String
            if let cell, let hitView {
                inCell = (hitView === cell || hitView.isDescendant(of: cell)) ? "inCell" : "chrome"
            } else {
                inCell = "noCell"
            }
            refreshHitProbeLabel(
                text:
                    "\(hitName) idx=\(indexText) \(inCell) cellH=\(cellHeight) contentH=\(contentHeight) y=\(Int(point.y))"
            )
        }

        private func refreshHitProbeLabel(text: String?) {
            guard DebugHitboxOverlayPresentation.isShowing else {
                hitProbeLabel?.isHidden = true
                return
            }
            let label = hitProbeLabel ?? UILabel()
            if hitProbeLabel == nil {
                label.font = .monospacedDigitSystemFont(ofSize: 8, weight: .medium)
                label.textColor = .systemYellow
                label.backgroundColor = UIColor.black.withAlphaComponent(0.72)
                label.numberOfLines = 2
                label.adjustsFontSizeToFitWidth = true
                label.minimumScaleFactor = 0.5
                label.isUserInteractionEnabled = false
                addSubview(label)
                hitProbeLabel = label
            }
            label.isHidden = false
            label.text = text ?? DebugHitboxOverlayPresentation.probeLine
            let width = min(bounds.width - 8, max(160, bounds.width - 8))
            label.frame = CGRect(x: 4, y: max(2, bounds.height - 30), width: width, height: 28)
            bringSubviewToFront(label)
        }
    #endif

    override func point(inside point: CGPoint, with event: UIEvent?) -> Bool {
        let result =
            bounds.contains(point)
            || (!expandButton.isHidden && expandedButtonHitFrame.contains(point))
        logTouch(
            "bar pointInside",
            point: point,
            lastLogTime: &lastPointInsideDiagnosticLogTime,
            extra: "inside=\(result)"
        )
        return result
    }

    override func hitTest(_ point: CGPoint, with event: UIEvent?) -> UIView? {
        #if DEBUG && KEYBOARD_WAKE_OWNER_PROBE
            if let button = wakeProbeButton, !button.isHidden, button.frame.contains(point) {
                return button.hitTest(button.convert(point, from: self), with: event)
            }
        #endif
        let superHit = super.hitTest(point, with: event)
        let result: UIView?
        let collectionPoint = collectionView.convert(point, from: self)
        let hitsCandidateItem =
            collectionView.frame.contains(point)
            && collectionView.indexPathForItem(at: collectionPoint) != nil
        if !hitsCandidateItem, !expandButton.isHidden, expandedButtonHitFrame.contains(point) {
            let buttonPoint = expandButton.convert(point, from: self)
            result = expandButton.hitTest(buttonPoint, with: event) ?? expandButton
        } else if bounds.contains(point), collectionView.frame.contains(point) {
            result = collectionView.hitTest(collectionPoint, with: event) ?? collectionView
        } else if bounds.contains(point) {
            result = self
        } else {
            result = nil
        }
        logTouch(
            "bar hitTest",
            point: point,
            lastLogTime: &lastHitTestDiagnosticLogTime,
            extra: "super=\(CandidateTouchDiagnostics.viewName(superHit)) "
                + "hit=\(CandidateTouchDiagnostics.viewName(result)) "
                + "collectionFrame=\(rectDescription(collectionView.frame)) "
                + "pan=\(CandidateTouchDiagnostics.gestureStateName(collectionView.panGestureRecognizer.state))"
        )
        #if DEBUG
            recordStructuredTouchIfNeeded(point: point, hitView: result, event: event)
            recordHitProbe(point: point, hitView: result)
        #endif
        return result
    }

    #if DEBUG
        private func recordStructuredTouchIfNeeded(point: CGPoint, hitView: UIView?, event: UIEvent?) {
            // Physical keyboard extensions may enter hit-testing before UIKit
            // exposes `.began`. Identity still deduplicates repeated hit-test
            // passes for the same single-finger operation.
            guard let touches = event?.allTouches,
                touches.count == 1,
                let touch = touches.first,
                touch.type == .direct
            else { return }
            guard touch !== lastStructuredTouch else { return }
            lastStructuredTouch = touch

            let band = DiagnosticEvent.CandidateTouchBand.classify(
                y: Double(point.y),
                height: Double(candidateBarHeight)
            )
            diagnosticSink?.recordCandidateTouchRouted(
                band: band,
                didHitCell: Self.hasCandidateCellAncestor(hitView)
            )
        }

        private static func hasCandidateCellAncestor(_ view: UIView?) -> Bool {
            var current = view
            while let candidate = current {
                if candidate is CandidateCollectionCell { return true }
                current = candidate.superview
            }
            return false
        }
    #endif

    private var expandedButtonHitFrame: CGRect {
        guard let button = expandButton as? CandidateBarExpandButton else { return expandButton.frame }
        let outsets = button.hitOutsets
        return ChromeTouchHitGeometry.candidateExpandButtonHitFrame(
            buttonFrame: button.frame,
            topOutset: outsets.top,
            leftOutset: outsets.left,
            bottomOutset: outsets.bottom,
            rightOutset: outsets.right,
            barBounds: bounds
        )
    }

    private func logTouch(
        _ name: String,
        point: CGPoint,
        lastLogTime: inout CFTimeInterval,
        extra: String
    ) {
        guard CandidateTouchDiagnostics.isEnabled else { return }
        let now = CACurrentMediaTime()
        guard now - lastLogTime >= CandidateTouchDiagnostics.minimumLogInterval else { return }
        lastLogTime = now
        Logger.shared.debug(
            "candidateTouch \(name) point=\(CandidateTouchDiagnostics.pointDescription(point)) "
                + "bounds=\(Int(bounds.width))x\(Int(bounds.height)) \(extra)",
            category: .display
        )
    }

    private func rectDescription(_ rect: CGRect) -> String {
        "(\(Int(rect.minX)),\(Int(rect.minY)),\(Int(rect.width)),\(Int(rect.height)))"
    }

    #if DEBUG && KEYBOARD_WAKE_OWNER_PROBE
        func installWakeOwnerProbeButton(target: Any?, action: Selector) {
            guard wakeProbeButton == nil else { return }
            let button = UIButton(type: .custom)
            button.translatesAutoresizingMaskIntoConstraints = false
            button.backgroundColor = UIColor.systemGray.withAlphaComponent(0.001)
            button.setTitleColor(.label, for: .normal)
            button.titleLabel?.font = .systemFont(ofSize: 12, weight: .medium)
            button.addTarget(target, action: action, for: .touchUpInside)
            button.isHidden = true
            addSubview(button)
            wakeProbeButton = button
            gestureBridge.wakeProbeButton = button
            NSLayoutConstraint.activate([
                button.trailingAnchor.constraint(equalTo: expandButton.leadingAnchor, constant: -2),
                button.topAnchor.constraint(equalTo: topAnchor),
                button.widthAnchor.constraint(equalToConstant: 44),
                button.heightAnchor.constraint(equalToConstant: min(candidateBarHeight, 44)),
            ])
            wakeProbeTrailingConstraint = collectionView.trailingAnchor.constraint(
                equalTo: button.leadingAnchor, constant: -2)
            let observer = WakeOwnerProbeTouchObserver()
            observer.cancelsTouchesInView = false
            observer.delaysTouchesBegan = false
            observer.delaysTouchesEnded = false
            observer.delegate = gestureBridge
            observer.onTouch = { [weak self] identifier, began in
                self?.onWakeOwnerProbeTouch?(identifier, began)
            }
            addGestureRecognizer(observer)
        }

        func setWakeOwnerProbeButton(visible: Bool, title: String) {
            guard let button = wakeProbeButton else { return }
            button.setTitle(title, for: .normal)
            button.accessibilityLabel = title == "观测" ? "开始 owner 观测" : "冻结并导出 owner 观测"
            guard button.isHidden == visible else { return }
            if visible {
                candidateTrailingConstraint.isActive = false
                wakeProbeTrailingConstraint?.isActive = true
